#include <iostream>
#include <string>

void swapValues(int& a, int& b) {
    int temp = a;
    a = b;
    b = temp;
}

void shout(const std::string& text) {   // read-only, nothing is copied
    std::cout << text << "!\n";
}

int main() {
    int x{1};
    int y{2};
    swapValues(x, y);
    std::cout << "x=" << x << " y=" << y << '\n';

    int& alias = x;   // alias is another name for x
    alias = 10;
    std::cout << "x=" << x << '\n';

    std::string name{"Grace"};
    shout(name);
}

#include <iostream>

int main() {
    int value{42};
    int* p = &value;        // p holds the address of value

    std::cout << *p << '\n';   // read through the pointer
    *p = 43;                   // write through the pointer
    std::cout << value << '\n';

    int other{7};
    p = &other;                // pointers can be re-pointed
    std::cout << *p << '\n';

    p = nullptr;               // points at nothing
    if (p == nullptr) {
        std::cout << "p is null\n";
    }
}

#include <iostream>
#include <string>
#include <vector>

struct Student {
    std::string name;
    int score;
};

// Returns the first student with that name, or nullptr if there is none.
const Student* findByName(const std::vector<Student>& students, const std::string& name) {
    for (const Student& s : students) {
        if (s.name == name) return &s;
    }
    return nullptr;
}

int main() {
    std::vector<Student> students{{"Ada", 91}, {"Linus", 78}};

    if (const Student* found = findByName(students, "Linus")) {
        std::cout << found->name << " scored " << found->score << '\n';
    }
    if (findByName(students, "Grace") == nullptr) {
        std::cout << "Grace not found\n";
    }
}

#include <iostream>
#include <vector>

void print(const std::vector<int>& v) {
    for (std::size_t i = 0; i < v.size(); ++i) {
        std::cout << (i == 0 ? "" : ", ") << v[i];
    }
    std::cout << '\n';
}

int main() {
    std::vector<int> prices{10, 20, 30};

    for (int p : prices) {        // p is a copy of each element
        p *= 2;
        std::cout << "doubled copy: " << p << '\n';
    }
    print(prices);                // unchanged

    for (int& p : prices) {       // p refers to the element itself
        p *= 2;
    }
    print(prices);                // changed
}

